-- Synthetic identities only. No emails or existing teams/games. Always ROLLBACK.
begin;
do $$
declare actor uuid:=gen_random_uuid(); peer uuid:=gen_random_uuid(); team uuid:=gen_random_uuid(); other_team uuid:=gen_random_uuid();
 season uuid:=gen_random_uuid(); player uuid:=gen_random_uuid(); other_player uuid:=gen_random_uuid(); cup uuid:=gen_random_uuid();
 day uuid:=gen_random_uuid(); game uuid:=gen_random_uuid(); next_game uuid:=gen_random_uuid(); command uuid:=gen_random_uuid();
 rules jsonb; changed jsonb; setup jsonb; view jsonb; g jsonb; result jsonb; state jsonb;
begin
 insert into auth.users(id) values(actor),(peer);
 insert into public.teams(id,name,created_by) values(team,'Manager Beverage rollback-only team',actor),(other_team,'Manager Beverage rollback-only other team',peer);
 insert into public.team_memberships(team_id,user_id,is_captain) values(team,actor,false),(team,peer,true),(other_team,peer,false);
 insert into public.team_seasons(id,team_id,name,created_by) values(season,team,'Manager Beverage rollback-only season',actor);
 insert into public.team_players(id,team_id,user_id,display_name,is_guest) values(player,team,actor,'Synthetic Manager',false),(other_player,team,peer,'Synthetic Member',false);
 rules:=jsonb_build_object('strikeout',1,'solo',1,'bandSolo',-1,'grandSlam',-1,'overLimit',1,'insidePark',-1,'multiRun',0);
 changed:=rules||jsonb_build_object('strikeout',4);
 perform set_config('request.jwt.claim.sub',actor::text,true);execute 'set local role authenticated';
 result:=public.da_change_team_beverage(team,gen_random_uuid(),0,jsonb_build_object('type','finalize','rules',rules));
 if result->>'status' is distinct from 'accepted' then raise exception 'Creator finalization failed'; end if;
 state:=public.da_read_team_beverage(team);
 if state->'management'->>'canEdit' is distinct from 'true' or state->'management'->>'lockedBy' is distinct from 'Synthetic Manager' or state->'management'->>'lockedAt' is null then raise exception 'Locker/manager metadata missing'; end if;
 perform public.da_create_scoring_competition(team,season,cup,'Tournament','Manager rollback-only cup',2,2);
 view:=public.da_read_scoring_season(team,season,'Overall');
 setup:=jsonb_build_object('type','start','gameId',game,'kind','Tournament','opponent','Synthetic old-rule opponent','battingMode','manual','lineup','[]'::jsonb,'rules',jsonb_build_object('version','Synthetic old rules','fenceLimit',2,'board',rules),'bands','{}'::jsonb);
 result:=public.da_start_scoring_game(team,season,day,date '2026-10-14',cup,gen_random_uuid(),0,(view->'tournaments'->0->>'revision')::bigint,setup);
 if result->>'status' is distinct from 'accepted' then raise exception 'Old game failed'; end if;
 view:=public.da_read_scoring_season(team,season,'Overall');select x into g from jsonb_array_elements(view->'games') x where x->'game'->>'id'=game::text;
 result:=public.da_apply_scoring_game_change(team,season,day,game,gen_random_uuid(),(g->>'dayRevision')::bigint,(g->>'tournamentRevision')::bigint,jsonb_build_object('type','score','gameId',game,'playId',gen_random_uuid(),'playerId',player,'outcome','Fence HR','runs',1,'rbi',1,'firstGameBand',true));
 if result->>'status' is distinct from 'accepted' then raise exception 'Legacy credit failed'; end if;
 result:=public.da_change_team_beverage(team,command,1,jsonb_build_object('type','replace','rules',changed));
 if result->>'status' is distinct from 'accepted' then raise exception 'Manager replacement failed'; end if;
 view:=public.da_read_scoring_season(team,season,'Overall');select x into g from jsonb_array_elements(view->'games') x where x->'game'->>'id'=game::text;
 if (view->'board'->>player::text)::integer is distinct from -1 or (g->'rules'->>'strikeout')::integer is distinct from 1 then raise exception 'Rule change rewrote old rules or credit'; end if;
 result:=public.da_apply_scoring_game_change(team,season,day,game,gen_random_uuid(),(g->>'dayRevision')::bigint,(g->>'tournamentRevision')::bigint,jsonb_build_object('type','score','gameId',game,'playId',gen_random_uuid(),'playerId',player,'outcome','K','runs',0,'rbi',0));
 view:=public.da_read_scoring_season(team,season,'Overall');
 if result->>'status' is distinct from 'accepted' or (view->'board'->>player::text)::integer is distinct from 0 then raise exception 'Old live game did not retain its charge'; end if;
 select x into g from jsonb_array_elements(view->'games') x where x->'game'->>'id'=game::text;
 setup:=jsonb_set(setup,'{gameId}',to_jsonb(next_game::text));setup:=jsonb_set(setup,'{rules,board}',changed);setup:=jsonb_set(setup,'{rules,version}',to_jsonb('Synthetic new rules'::text));
 result:=public.da_start_scoring_game(team,season,day,date '2026-10-14',cup,gen_random_uuid(),(g->>'dayRevision')::bigint,(g->>'tournamentRevision')::bigint,setup);
 if result->>'status' is distinct from 'accepted' then raise exception 'New game failed'; end if;
 view:=public.da_read_scoring_season(team,season,'Overall');select x into g from jsonb_array_elements(view->'games') x where x->'game'->>'id'=next_game::text;
 if (g->'rules'->>'strikeout')::integer is distinct from 4 or (g->'evaluation'->>'fenceUsed')::integer is distinct from 0 then raise exception 'New defaults or HR reset incorrect'; end if;
 result:=public.da_apply_scoring_game_change(team,season,day,next_game,gen_random_uuid(),(g->>'dayRevision')::bigint,(g->>'tournamentRevision')::bigint,jsonb_build_object('type','score','gameId',next_game,'playId',gen_random_uuid(),'playerId',player,'outcome','K','runs',0,'rbi',0));
 view:=public.da_read_scoring_season(team,season,'Overall');
 if result->>'status' is distinct from 'accepted' or (view->'board'->>player::text)::integer is distinct from 4 then raise exception 'New game did not use current amount'; end if;
 perform set_config('request.jwt.claim.sub',peer::text,true);
 state:=public.da_read_team_beverage(team);
 if state->'management'->>'canEdit' is distinct from 'false' or state->'management'->>'lockedBy' is distinct from 'Synthetic Manager' then raise exception 'Captain/member permission wrong'; end if;
 begin perform public.da_change_team_beverage(team,gen_random_uuid(),2,jsonb_build_object('type','replace','rules',rules));raise exception 'Captain changed rules';exception when insufficient_privilege then null;end;
 begin perform public.da_change_team_beverage(team,gen_random_uuid(),2,jsonb_build_object('type','finalize','rules',rules));raise exception 'Member finalized rules';exception when insufficient_privilege then null;end;
 result:=public.da_change_team_beverage(team,gen_random_uuid(),2,jsonb_build_object('type','participation','participating',false));
 if result->>'status' is distinct from 'accepted' then raise exception 'Member choice denied'; end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 result:=public.da_change_team_beverage(team,command,1,jsonb_build_object('type','replace','rules',changed));
 if result->>'duplicate' is distinct from 'true' then raise exception 'Stable retry failed'; end if;
 result:=public.da_change_team_beverage(team,gen_random_uuid(),0,jsonb_build_object('type','replace','rules',rules));
 if result->>'status' is distinct from 'conflict' then raise exception 'Stale manager revision accepted'; end if;
 begin perform public.da_read_team_beverage(other_team);raise exception 'Other team readable';exception when insufficient_privilege then null;end;
 begin perform public.da_change_team_beverage(team,command,3,jsonb_build_object('type','replace','rules',rules));raise exception 'ID reuse accepted';exception when sqlstate '22023' then null;end;
 execute 'reset role';
 if not exists(select 1 from private.beverage_commands where team_id=team and command_id=command and previous_rules=rules and payload->'rules'=changed and actor_id=actor) then raise exception 'Before/after audit missing'; end if;
 update public.team_memberships set active=false where team_id=team and user_id=actor;
 execute 'set local role authenticated';
 begin perform public.da_read_team_beverage(team);raise exception 'Inactive creator read';exception when insufficient_privilege then null;end;
 begin perform public.da_change_team_beverage(team,gen_random_uuid(),3,jsonb_build_object('type','replace','rules',rules));raise exception 'Inactive creator write';exception when insufficient_privilege then null;end;
 execute 'set local role anon';
 begin perform public.da_read_team_beverage(team);raise exception 'Anonymous read';exception when insufficient_privilege then null;end;
 execute 'reset role';
end $$;
rollback;
